arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s\n' "x-access-token" ;;
  *[Pp]assword*) printf '%s\n' "$GITHUB_TOKEN" ;;
  *) printf '%s\n' "" ;;
esac
EOF
chmod 700 /tmp/askpass.sh
git -C /home/runner/work/phoebe-convo commit --allow-empty -F /tmp/phoebe-msg.txt -c user.name="github-actions[bot]" -c user.email="41898282+github-actions[bot]@users.noreply.github.com" 2>&1 | tail -3
git -C /home/runner/work/phoebe-convo log -1 --format='%H %an <%ae> %s'
